import assert from 'node:assert/strict';
import { createPushGate } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/knock-g2-2/bot.mjs';

const tokyo = { id: 'u_1', timeZone: 'Asia/Tokyo', quietStart: '22:00', quietEnd: '07:00', dailyCap: 3 };
const at = (iso) => new Date(iso);
let n = 0;
const ok = (name, fn) => { fn(); n++; console.log('ok -', name); };

ok('quiet: 22:00 local is blocked (start inclusive)', () => {
  const g = createPushGate();
  assert.deepEqual(g.attempt(tokyo, at('2026-10-22T13:00:00Z')), { allowed: false, reason: 'quiet_hours' });
});
ok('quiet: 00:30 local next day is blocked (window crosses midnight)', () => {
  const g = createPushGate();
  assert.deepEqual(g.attempt(tokyo, at('2026-10-22T15:30:00Z')), { allowed: false, reason: 'quiet_hours' });
});
ok('quiet: 06:59 local is blocked', () => {
  const g = createPushGate();
  assert.equal(g.attempt(tokyo, at('2026-10-22T21:59:00Z')).reason, 'quiet_hours');
});
ok('quiet: 07:00 local is allowed (end exclusive)', () => {
  const g = createPushGate();
  assert.deepEqual(g.attempt(tokyo, at('2026-10-22T22:00:00Z')), { allowed: true, reason: null });
});
ok('quiet: non-wrapping window uses the user zone, not UTC', () => {
  const g = createPushGate();
  const u = { id: 'u_2', timeZone: 'UTC', quietStart: '13:00', quietEnd: '14:00', dailyCap: 9 };
  assert.equal(g.attempt(u, at('2026-10-22T13:30:00Z')).reason, 'quiet_hours');
  assert.equal(g.attempt(u, at('2026-10-22T14:00:00Z')).allowed, true);
  const ny = { ...u, id: 'u_3', timeZone: 'America/New_York' }; // 13:30Z = 09:30 NY
  assert.equal(g.attempt(ny, at('2026-10-22T13:30:00Z')).allowed, true);
});
ok('quiet: equal start and end means no quiet window', () => {
  const g = createPushGate();
  const u = { ...tokyo, quietStart: '08:00', quietEnd: '08:00', dailyCap: 9 };
  assert.equal(g.attempt(u, at('2026-10-22T23:00:00Z')).allowed, true);
});

ok('cap: 3 per local day, 4th denied, reset at local midnight', () => {
  const g = createPushGate();
  assert.equal(g.attempt(tokyo, at('2026-10-22T00:00:00Z')).allowed, true); // 09:00 JST
  assert.equal(g.attempt(tokyo, at('2026-10-22T03:00:00Z')).allowed, true); // 12:00 JST
  assert.equal(g.attempt(tokyo, at('2026-10-22T11:00:00Z')).allowed, true); // 20:00 JST
  assert.deepEqual(g.attempt(tokyo, at('2026-10-22T12:00:00Z')), { allowed: false, reason: 'daily_cap' }); // 21:00 JST
  assert.deepEqual(g.attempt(tokyo, at('2026-10-22T21:00:00Z')), { allowed: true, reason: null }); // 06:00 JST? no: quiet
});
