import assert from 'node:assert/strict';
import { createPushGate } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/knock-g2-2/bot.mjs';

const tokyo = { id: 'u_1', timeZone: 'Asia/Tokyo', quietStart: '22:00', quietEnd: '07:00', dailyCap: 3 };
const at = (iso) => new Date(iso);
const allow = { allowed: true, reason: null };
const deny = (reason) => ({ allowed: false, reason });
let n = 0;
const ok = (name, fn) => { fn(); n++; console.log('ok -', name); };

ok('quiet: 22:00 local blocked (start inclusive)', () => {
  assert.deepEqual(createPushGate().attempt(tokyo, at('2026-10-22T13:00:00Z')), deny('quiet_hours'));
});
ok('quiet: 00:30 local blocked (window crosses midnight)', () => {
  assert.deepEqual(createPushGate().attempt(tokyo, at('2026-10-22T15:30:00Z')), deny('quiet_hours'));
});
ok('quiet: 06:59 local blocked', () => {
  assert.deepEqual(createPushGate().attempt(tokyo, at('2026-10-22T21:59:00Z')), deny('quiet_hours'));
});
ok('quiet: 07:00 local allowed (end exclusive)', () => {
  assert.deepEqual(createPushGate().attempt(tokyo, at('2026-10-22T22:00:00Z')), allow);
});
ok('quiet: non-wrapping window evaluated in user zone', () => {
  const g = createPushGate();
  const u = { id: 'u_2', timeZone: 'UTC', quietStart: '13:00', quietEnd: '14:00', dailyCap: 9 };
  assert.deepEqual(g.attempt(u, at('2026-10-22T13:30:00Z')), deny('quiet_hours'));
  assert.deepEqual(g.attempt(u, at('2026-10-22T14:00:00Z')), allow);
  const ny = { ...u, id: 'u_3', timeZone: 'America/New_York' }; // 13:30Z = 09:30 NY
  assert.deepEqual(g.attempt(ny, at('2026-10-22T13:30:00Z')), allow);
});
ok('quiet: equal start and end means no quiet window', () => {
  const u = { ...tokyo, quietStart: '08:00', quietEnd: '08:00', dailyCap: 9 };
  assert.deepEqual(createPushGate().attempt(u, at('2026-10-22T23:00:00Z')), allow);
});

ok('cap: 3 per local day, 4th denied, count resets at local midnight', () => {
  const g = createPushGate();
  assert.deepEqual(g.attempt(tokyo, at('2026-10-22T00:00:00Z')), allow); // 09:00 JST
  assert.deepEqual(g.attempt(tokyo, at('2026-10-22T03:00:00Z')), allow); // 12:00 JST
  assert.deepEqual(g.attempt(tokyo, at('2026-10-22T11:00:00Z')), allow); // 20:00 JST
  assert.deepEqual(g.attempt(tokyo, at('2026-10-22T12:00:00Z')), deny('daily_cap')); // 21:00 JST
  assert.deepEqual(g.attempt(tokyo, at('2026-10-22T22:00:00Z')), allow); // 07:00 JST Oct 23
});
ok('cap: calendar day, not rolling 24h (23:50 and 00:10 both allowed)', () => {
  const g = createPushGate();
  const u = { id: 'u_4', timeZone: 'America/New_York', quietStart: '00:00', quietEnd: '00:00', dailyCap: 1 };
  assert.deepEqual(g.attempt(u, at('2026-10-23T03:50:00Z')), allow); // 23:50 NY Oct 22
  assert.deepEqual(g.attempt(u, at('2026-10-23T04:10:00Z')), allow); // 00:10 NY Oct 23
  assert.deepEqual(g.attempt(u, at('2026-10-23T04:20:00Z')), deny('daily_cap'));
});
ok('cap: denied calls do not consume the cap', () => {
  const g = createPushGate();
  const u = { ...tokyo, dailyCap: 1 };
  assert.deepEqual(g.attempt(u, at('2026-10-22T13:00:00Z')), deny('quiet_hours'));
  assert.deepEqual(g.attempt(u, at('2026-10-22T14:00:00Z')), allow); // 23:00 JST, still quiet? 23:00 is quiet
});
ok('cap: quiet denial does not consume cap (use daytime)', () => {
  const g = createPushGate();
  const u = { ...tokyo, dailyCap: 1 };
  assert.deepEqual(g.attempt(u, at('2026-10-22T13:00:00Z')), deny('quiet_hours'));
  assert.deepEqual(g.attempt(u, at('2026-10-22T03:00:00Z')), allow); // 12:00 JST
});
ok('cap: dailyCap 0 always denies with daily_cap', () => {
  const u = { ...tokyo, dailyCap: 0 };
  assert.deepEqual(createPushGate().attempt(u, at('2026-10-22T03:00:00Z')), deny('daily_cap'));
});
ok('cap: cap is read per call (raised cap takes effect)', () => {
  const g = createPushGate();
  const u = { ...tokyo, dailyCap: 1 };
  assert.deepEqual(g.attempt(u, at('2026-10-22T00:00:00Z')), allow);
  assert.deepEqual(g.attempt(u, at('2026-10-22T01:00:00Z')), deny('daily_cap'));
  assert.deepEqual(g.attempt({ ...u, dailyCap: 2 }, at('2026-10-22T01:00:00Z')), allow);
});
ok('isolation: users and gates have independent history', () => {
  const g1 = createPushGate();
  const g2 = createPushGate();
  const a = { ...tokyo, dailyCap: 1 };
  const b = { ...tokyo, id: 'u_other', dailyCap: 1 };
  assert.deepEqual(g1.attempt(a, at('2026-10-22T00:00:00Z')), allow);
  assert.deepEqual(g1.attempt(b, at('2026-10-22T00:00:00Z')), allow);
  assert.deepEqual(g2.attempt(a, at('2026-10-22T00:00:00Z')), allow);
  assert.deepEqual(g1.attempt(a, at('2026-10-22T01:00:00Z')), deny('daily_cap'));
});
ok('zone change: count uses the zone passed in this call', () => {
  const g = createPushGate();
  const u = { id: 'u_5', timeZone: 'UTC', quietStart: '00:00', quietEnd: '00:00', dailyCap: 1 };
  assert.deepEqual(g.attempt(u, at('2026-10-22T23:30:00Z')), allow); // Oct 22 UTC
  // Same instant-ish, device now in Tokyo = Oct 23 08:30 JST: new local day
  assert.deepEqual(g.attempt({ ...u, timeZone: 'Asia/Tokyo' }, at('2026-10-22T23:31:00Z')), allow);
});
ok('DST: New York fall-back day counts as one local day', () => {
  const g = createPushGate();
  const u = { id: 'u_6', timeZone: 'America/New_York', quietStart: '00:00', quietEnd: '00:00', dailyCap: 2 };
  assert.deepEqual(g.attempt(u, at('2026-11-01T05:30:00Z')), allow); // 01:30 EDT Nov 1
  assert.deepEqual(g.attempt(u, at('2026-11-01T06:30:00Z')), allow); // 01:30 EST Nov 1 (second pass)
  assert.deepEqual(g.attempt(u, at('2026-11-01T07:30:00Z')), deny('daily_cap'));
});
ok('input: bad timeZone, bad HH:MM, bad cap, bad now throw', () => {
  const g = createPushGate();
  const now = at('2026-10-22T00:00:00Z');
  assert.throws(() => g.attempt({ ...tokyo, timeZone: 'Mars/Olympus' }, now), TypeError);
  assert.throws(() => g.attempt({ ...tokyo, quietStart: '24:00' }, now), TypeError);
  assert.throws(() => g.attempt({ ...tokyo, quietEnd: '7:00' }, now), TypeError);
  assert.throws(() => g.attempt({ ...tokyo, dailyCap: -1 }, now), TypeError);
  assert.throws(() => g.attempt(tokyo, new Date('nope')), TypeError);
});
ok('reasons are distinct snake_case codes', () => {
  assert.notEqual('quiet_hours', 'daily_cap');
});
console.log(`\n${n} groups passed`);
EOF
